class Solution {
    public int minimumRightRotations(int[] nums) {
        int n = nums.length;
        int descent = -1;
        for (int i = 0; i < n; i++) {
            int next = (i + 1) % n;
            if (nums[i] > nums[next]) {
                if (descent != -1) {
                    return -1;
                }
                descent = i;
            }
        }
        if (descent == -1 || descent == n - 1) {
            return 0;
        }
        return n - descent - 1;
    }
}

class Solution {
    public int minimumRightRotations(int[] nums) {
        int n = nums.length;
        int pivot = -1;
        for (int i = 0; i + 1 < n; i++) {
            if (nums[i] > nums[i + 1]) {
                if (pivot != -1) {
                    return -1;
                }
                pivot = i + 1;
            }
        }
        if (pivot == -1) {
            return 0;
        }
        for (int offset = 1; offset < n; offset++) {
            int previous = nums[(pivot + offset - 1) % n];
            int current = nums[(pivot + offset) % n];
            if (previous > current) {
                return -1;
            }
        }
        return n - pivot;
    }
}

class Solution {
    public int minimumRightRotations(int[] nums) {
        int n = nums.length;
        for (int rotation = 0; rotation < n; rotation++) {
            boolean sorted = true;
            for (int i = 1; i < n; i++) {
                int previous = nums[(i - 1 - rotation + n) % n];
                int current = nums[(i - rotation + n) % n];
                if (previous > current) {
                    sorted = false;
                    break;
                }
            }
            if (sorted) {
                return rotation;
            }
        }
        return -1;
    }
}

class Solution {
    public int minimumRightRotations(int[] nums) {
        int n = nums.length;
        int[] sorted = nums.clone();
        java.util.Arrays.sort(sorted);
        int best = n;
        for (int start = 0; start < n; start++) {
            boolean matches = true;
            for (int i = 0; i < n; i++) {
                if (nums[(start + i) % n] != sorted[i]) {
                    matches = false;
                    break;
                }
            }
            if (matches) {
                best = Math.min(best, (n - start) % n);
            }
        }
        return best == n ? -1 : best;
    }
}

class Solution {
    public int minimumRightRotations(int[] nums) {
        int n = nums.length;
        int[] pattern = nums.clone();
        java.util.Arrays.sort(pattern);
        int[] lps = buildLps(pattern);
        int best = Integer.MAX_VALUE;
        int matched = 0;
        for (int i = 0; i < 2 * n - 1; i++) {
            int value = nums[i % n];
            while (matched > 0 && value != pattern[matched]) {
                matched = lps[matched - 1];
            }
            if (value == pattern[matched]) {
                matched++;
            }
            if (matched == n) {
                int start = i - n + 1;
                if (start < n) {
                    best = Math.min(best, (n - start) % n);
                }
                matched = lps[matched - 1];
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }

    private int[] buildLps(int[] pattern) {
        int[] lps = new int[pattern.length];
        int length = 0;
        for (int i = 1; i < pattern.length; i++) {
            while (length > 0 && pattern[i] != pattern[length]) {
                length = lps[length - 1];
            }
            if (pattern[i] == pattern[length]) {
                length++;
                lps[i] = length;
            }
        }
        return lps;
    }
}
